mapper.update:
UPDATE community_push_deliveries d SET status='SENDING',attempts=attempts+1,claim_token=#{claimToken},lease_until=#{leaseUntil,jdbcType=TIMESTAMP}
WHERE d.notification_id=#{notificationId} AND d.subscription_id=#{subscriptionId}
  AND d.attempts < 3 AND d.next_attempt_at <= #{now,jdbcType=TIMESTAMP}
  AND (d.status IN ('PENDING','RETRY') OR (d.status='SENDING' AND d.lease_until <= #{now,jdbcType=TIMESTAMP}))
  AND EXISTS (
    SELECT 1 FROM user_notifications n JOIN user_push_subscriptions p ON p.user_id=n.user_id JOIN users u ON u.user_id=p.user_id
    WHERE n.notification_id=d.notification_id AND p.subscription_id=d.subscription_id AND p.user_id=#{userId}
      AND 
  )
